REPLACE = {'frontend/src/caseSwitcher.css': {'before': 'f4333fd71d40d7b7c3c20f22936d1e52946a72b907b762834b8e2569a5d433df', 'after': '/* The case list as a macOS source list. */\n.sl { display: flex; flex-direction: column; }\n.sl-section { display: flex; justify-content: space-between; align-items: baseline; padding: 14px 10px 6px;\n              font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase;\n              letter-spacing: 0.07em; color: var(--label-3); }\n.sl-count { font-variant-numeric: tabular-nums; font-weight: var(--font-weight-medium); color: var(--label-3); letter-spacing: 0; }\n.sl-wrap { position: relative; }\n.sl-group { margin-bottom: 2px; }\n.sl-group-head { display: flex; align-items: center; gap: 7px; width: 100%; padding: 6px 10px 4px 6px; border: 0; background: transparent;\n                 cursor: default; font: inherit; font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold);\n                 color: var(--label-2); border-radius: 7px; text-align: left; position: relative; z-index: 1; }\n.sl-group-head:hover { color: var(--label-1); background: var(--fill-hover); }\n.sl-group-head:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: -1px; }\n.sl-chev { width: 6px; height: 6px; margin: 0 2px; border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor;\n           transform: rotate(45deg) translate(-1px, -1px); transition: transform 260ms var(--ease-spring); opacity: 0.7; }\n.sl-group.is-closed .sl-chev { transform: rotate(-45deg); }\n.sl-fam { width: 15px; height: 15px; fill: none; stroke: var(--accent); stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }\n.sl-fam circle[r="1.4"] { fill: var(--accent); stroke: none; }\n.sl-group-name { flex: 1; }\n/* groups open and close by animating their height */\n.sl-rows { display: grid; grid-template-rows: 1fr; transition: grid-template-rows 300ms cubic-bezier(0.22, 1, 0.36, 1), opacity 240ms ease; }\n.sl-rows > ul { min-height: 0; overflow: hidden; margin: 0; padding: 0; list-style: none; }\n.sl-group.is-closed .sl-rows { grid-template-rows: 0fr; opacity: 0; }\n\n.sl-row { display: flex; align-items: center; gap: 10px; width: 100%; padding: 7px 10px 7px 12px; }\n.sl-row .case-text { flex: 1; min-width: 0; display: flex; flex-direction: column; }\n.sl-row .case-id { font-size: var(--font-size-sm); font-weight: var(--font-weight-medium); }\n.sl-row .case-description { font-family: var(--font-mono); font-size: 11px; opacity: 0.75; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.sl-outcome { flex: none; width: 17px; height: 17px; display: inline-grid; place-items: center; }\n.sl-outcome svg { width: 17px; height: 17px; fill: none; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.sl-outcome.is-named svg { stroke: var(--status-green); }\n.sl-outcome.is-named svg circle { fill: rgba(48, 209, 88, 0.14); }\n.sl-outcome.is-abstain svg { stroke: var(--status-orange); }\n.sl-outcome.is-abstain svg circle { fill: rgba(255, 159, 10, 0.14); }\n.sl-fit { flex: none; display: inline-flex; align-items: center; gap: 4px; font-family: var(--font-mono); font-size: 10.5px;\n          font-variant-numeric: tabular-nums; color: var(--label-2); }\n.sl-fit svg { width: 14px; height: 14px; }\n.sl-fit-track { fill: none; stroke: var(--fill-pressed); stroke-width: 2.2; }\n.sl-fit-arc { fill: none; stroke: #64d2ff; stroke-width: 2.2; stroke-linecap: round; }\n.sl-fit.is-below .sl-fit-arc { stroke: var(--status-orange); }\n/* on the selection, everything takes the selection\'s colour */\n.sl-row.is-active .case-description, .sl-row.is-active .sl-fit { color: inherit; opacity: 0.85; }\n.sl-row.is-active .sl-outcome svg { stroke: currentColor; }\n.sl-row.is-active .sl-outcome svg circle { fill: rgba(255, 255, 255, 0.2); }\n.sl-row.is-active .sl-fit-arc { stroke: #fff; }\n.sl-row.is-active .sl-fit-track { stroke: rgba(255, 255, 255, 0.3); }\n\n.sl-legend { display: flex; flex-wrap: wrap; gap: 6px 12px; margin-top: auto; padding: 16px 10px 4px; font-size: var(--font-size-xxs); color: var(--label-3); }\n.sl-legend span { display: inline-flex; align-items: center; gap: 5px; }\n.sl-legend .sl-outcome, .sl-legend .sl-outcome svg { width: 12px; height: 12px; }\n@media (prefers-reduced-motion: reduce) { .sl-rows, .sl-chev { transition: none; } }\n/* the sidebar lays out as a column so the legend sits at its foot */\n.finder-sidebar { display: flex; flex-direction: column; }\n.finder-sidebar > .sl { flex: 1; }\n\n/* the selection glides between rows on a gentle spring, with a soft glow */\n.case-highlight { box-shadow: 0 4px 14px rgba(10, 132, 255, 0.35), inset 0 0.5px 0 rgba(255, 255, 255, 0.25); }\n.case-highlight.is-ready { transition: transform 420ms cubic-bezier(0.34, 1.3, 0.64, 1), height 420ms cubic-bezier(0.34, 1.3, 0.64, 1), opacity 200ms ease; }\n.sl-row { transition: color 200ms ease, background-color 120ms ease, transform 160ms var(--ease-spring); }\n.sl-row:active { transform: scale(0.98); }\n.sl-row.is-active .case-id { font-weight: var(--font-weight-semibold); }\n@media (prefers-reduced-motion: reduce) {\n  .case-highlight.is-ready { transition: none; }\n  .finder-content, .finder-content > .finder-features, .finder-content > .finder-details { transition: none; animation: none; }\n  .finder-content.is-leaving { filter: none; transform: none; }\n  .finder-content.is-leaving::before { animation: none; opacity: 0; }\n}\n'}, 'frontend/src/shell.css': {'before': 'dacdcb00869d62b0d1db254e7c4afc52d8ee40941222236af9e2fe96d099d415', 'after': '/*\n * App shell, in the manner of a native macOS window: a unified translucent\n * toolbar, a vibrant source-list sidebar with one selection that slides\n * between rows, a content column of sections divided by hairlines rather than\n * boxed cards, and a translucent inspector.\n *\n * Tokens come from index.css. Nothing here is case-specific: panels keep\n * their own internal styles in dashboard.css and inherit the theme through\n * the aliased legacy variables.\n */\n\n/* ----------------------------------------------------------------- window */\n\n.app-shell {\n  height: 100vh;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  background: var(--window-bg);\n}\n\n.finder-layout {\n  display: flex;\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.finder-content {\n  flex: 1;\n  display: flex;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n}\n\n/* ---------------------------------------------------------------- toolbar */\n\n.topbar {\n  position: relative;\n  z-index: 5;\n  display: flex;\n  align-items: center;\n  gap: var(--space-4);\n  height: 52px;\n  padding: 0 var(--space-4) 0 var(--space-5);\n  flex-shrink: 0;\n  background: var(--material-bar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-bottom: 1px solid var(--separator);\n}\n\n.wordmark {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  min-width: 0;\n  white-space: nowrap;\n  font-family: var(--font-body);\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: -0.003em;\n  color: var(--label-1);\n}\n\n.wordmark-mark {\n  width: 18px;\n  height: 18px;\n  flex: 0 0 auto;\n  border-radius: 5px;\n}\n\n.wordmark-sub {\n  font-weight: var(--font-weight-normal);\n  color: var(--label-2);\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.topbar-trailing {\n  display: flex;\n  align-items: center;\n  gap: var(--space-3);\n  margin-left: auto;\n}\n\n.topbar-meta {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n/* ---------------------------------------------------------------- badges */\n\n.tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  height: 20px;\n  padding: 0 var(--space-2);\n  border: 0;\n  border-radius: 999px;\n  background: var(--fill-hover);\n  color: var(--label-2);\n  font-family: var(--font-body);\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-medium);\n  letter-spacing: 0.005em;\n  line-height: 1;\n  text-transform: none;\n  white-space: nowrap;\n}\n\n.tag-teal,\n.tag-amber,\n.tag-green,\n.tag-red {\n  font-variant-caps: normal;\n}\n\n.tag-teal::before,\n.tag-amber::before,\n.tag-green::before,\n.tag-red::before {\n  content: "";\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: currentColor;\n}\n\n.tag-teal  { color: var(--accent);        background: var(--accent-soft); }\n.tag-amber { color: var(--status-orange); background: var(--status-orange-soft); }\n.tag-green { color: var(--status-green);  background: var(--status-green-soft); }\n.tag-red   { color: var(--status-red);    background: var(--status-red-soft); }\n\n/* ---------------------------------------------------------------- sidebar */\n\n.finder-sidebar {\n  width: 264px;\n  min-width: 264px;\n  flex-shrink: 0;\n  overflow-y: auto;\n  padding: var(--space-3) 10px var(--space-4);\n  background: var(--material-sidebar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-right: 1px solid var(--separator);\n}\n\n.case-switcher {\n  display: flex;\n  flex-direction: column;\n}\n\n.case-switcher-label {\n  display: block;\n  padding: 6px 10px 6px;\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: 0.01em;\n  color: var(--label-3);\n}\n\n.case-list-wrap {\n  position: relative;\n}\n\n.case-list {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* One selection that travels between rows instead of colours swapping. */\n.case-highlight {\n  position: absolute;\n  z-index: 0;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: var(--h, 0px);\n  transform: translateY(var(--y, 0px));\n  border-radius: 7px;\n  background: var(--accent);\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14), inset 0 0.5px 0 rgba(255, 255, 255, 0.22);\n  opacity: 0;\n  pointer-events: none;\n}\n\n.case-highlight.is-ready {\n  opacity: 1;\n  transition: transform var(--dur-base) var(--ease-spring),\n              height var(--dur-base) var(--ease-spring),\n              opacity var(--dur-fast) ease;\n}\n\n.case-item {\n  position: relative;\n  width: 100%;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 7px 10px;\n  border: 0;\n  border-radius: 7px;\n  background: transparent;\n  color: var(--label-1);\n  font: inherit;\n  text-align: left;\n  cursor: default;\n  transition: background-color var(--dur-fast) ease,\n              color var(--dur-base) var(--ease-out),\n              transform var(--dur-base) var(--ease-spring);\n}\n\n.case-item:hover:not(.is-active) {\n  background: var(--fill-hover);\n}\n\n.case-item:active {\n  transform: scale(0.98);\n  transition-duration: var(--dur-fast), var(--dur-fast), var(--dur-fast);\n}\n\n.case-item.is-active {\n  color: var(--on-accent);\n}\n\n.case-item:focus-visible {\n  outline: 3px solid var(--accent-ring);\n  outline-offset: 0;\n}\n\n.case-text {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  line-height: 1.25;\n}\n\n.case-id {\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-medium);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.case-description {\n  font-size: var(--font-size-xs);\n  color: var(--label-2);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  transition: color var(--dur-base) var(--ease-out);\n}\n\n.case-item.is-active .case-description {\n  color: rgba(255, 255, 255, 0.8);\n}\n\n.case-indicator {\n  flex: 0 0 auto;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  box-shadow: inset 0 0 0 0.5px rgba(0, 0, 0, 0.12);\n  transition: background-color var(--dur-base) var(--ease-out);\n}\n\n.indicator-known   { background: var(--status-green); }\n.indicator-unknown { background: var(--status-orange); }\n\n.case-item.is-active .indicator-known,\n.case-item.is-active .indicator-unknown {\n  background: var(--on-accent);\n}\n\n/* ---------------------------------------------------------------- content */\n\n.finder-features {\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  padding: 0 var(--space-7) var(--space-8);\n  background: var(--content-bg);\n}\n\n.finder-features > * {\n  width: 100%;\n  max-width: 1040px;\n  margin-inline: auto;\n}\n\n/* Sections, not cards: no border, fill or shadow; hairlines between them. */\n.panel {\n  flex-shrink: 0;\n  padding: var(--space-6) 0;\n  border: 0;\n  border-top: 1px solid var(--separator);\n  border-radius: 0;\n  background: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n  box-shadow: none;\n}\n\n.panel-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: var(--space-2) var(--space-3);\n  margin-bottom: 14px;\n}\n\n.panel-head h2 {\n  font-family: var(--font-display);\n  font-size: var(--font-size-md);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: -0.012em;\n  color: var(--label-1);\n}\n\n/* Section titles pin while their section scrolls beneath - with a scroll-edge\n   effect, not a translucent material. At rest the header is clear. While its\n   card\'s content passes under it (is-stuck, set by stickyHeaders.js) it takes\n   the pane\'s own solid background, a hairline, and a soft fade below, so\n   content dissolves under it instead of being smeared into a blurred band. */\n.finder-features .panel > .panel-head {\n  position: sticky;\n  top: 0;\n  z-index: 3;\n  margin: calc(-1 * var(--space-6)) calc(-1 * var(--space-3)) 14px;\n  padding: var(--space-3) var(--space-3) var(--space-2);\n  background: transparent;\n  transition: background-color 160ms ease, box-shadow 160ms ease;\n}\n.finder-features .panel > .panel-head::after {\n  content: ""; position: absolute; left: 0; right: 0; top: 100%; height: 18px; pointer-events: none;\n  background: linear-gradient(to bottom, var(--content-bg), color-mix(in srgb, var(--content-bg) 0%, transparent));\n  opacity: 0; transition: opacity 160ms ease;\n}\n.finder-features .panel > .panel-head.is-stuck {\n  background: var(--content-bg);\n  box-shadow: 0 0.5px 0 var(--separator);\n}\n.finder-features .panel > .panel-head.is-stuck::after { opacity: 1; }\n\n.finder-features .panel {\n  padding-top: var(--space-6);\n}\n\n.finder-features > .verdict {\n  margin-top: var(--space-6);\n  margin-bottom: var(--space-6);\n}\n\n/* -------------------------------------------------------------- inspector */\n\n.finder-details {\n  width: 340px;\n  min-width: 340px;\n  flex-shrink: 0;\n  min-height: 0;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  padding: var(--space-5);\n  background: var(--material-sidebar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-left: 1px solid var(--separator);\n}\n\n.finder-details .panel {\n  padding: 0;\n  border-top: 0;\n}\n\n.finder-details .console-panel {\n  flex: 1;\n  min-height: 320px;\n  padding: 0;\n  background: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n  border-radius: 0;\n}\n\n.report-buttons {\n  display: flex;\n  gap: var(--space-2);\n  margin-bottom: var(--space-5);\n}\n\n/* ---------------------------------------------------------------- buttons */\n\n.report-button {\n  flex: 1;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 28px;\n  padding: 0 var(--space-3);\n  border: 0;\n  border-radius: 7px;\n  background: var(--control-bg);\n  color: var(--label-1);\n  box-shadow: var(--shadow-control);\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-medium);\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: default;\n  transition: transform var(--dur-base) var(--ease-spring),\n              background-color var(--dur-fast) ease;\n}\n\n.report-button:hover {\n  background: var(--control-bg-hover);\n}\n\n.report-button:active {\n  transform: scale(0.97);\n  background: var(--control-bg-pressed);\n  transition-duration: var(--dur-fast);\n}\n\n/* Panel controls: same springs, no lifts, no colour flashes. */\n.suggestion,\n.frag-step,\n.console-input-row button,\n.probe-close,\n.metric-info-trigger {\n  transition: transform var(--dur-base) var(--ease-spring),\n              background-color var(--dur-fast) ease,\n              border-color var(--dur-fast) ease,\n              color var(--dur-fast) ease;\n}\n\n.suggestion {\n  border: 0;\n  border-radius: var(--radius-md);\n  background: var(--surface-sunken);\n  padding: 9px 12px;\n  font-size: var(--font-size-sm);\n  color: var(--label-1);\n  cursor: default;\n}\n\n.suggestion:hover {\n  background: var(--fill-pressed);\n  box-shadow: none;\n  transform: none;\n}\n\n.frag-step {\n  border-radius: var(--radius-sm);\n  background: var(--surface-raised);\n  cursor: default;\n}\n\n.frag-step:hover {\n  background: var(--fill-hover);\n  transform: none;\n}\n\n.console-input-row {\n  border-top: 1px solid var(--separator);\n  padding-top: var(--space-3);\n  margin-top: var(--space-2);\n}\n\n.console-input-row input {\n  height: 28px;\n  padding: 0 10px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n  font-size: var(--font-size-sm);\n  transition: box-shadow var(--dur-fast) ease;\n}\n\n.console-input-row input:focus {\n  outline: none;\n  box-shadow: var(--shadow-control), 0 0 0 3px var(--accent-ring);\n}\n\n.console-input-row button {\n  height: 28px;\n  padding: 0 14px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--accent);\n  color: var(--on-accent);\n  box-shadow: 0 1px 1.5px rgba(0, 0, 0, 0.12), inset 0 0.5px 0 rgba(255, 255, 255, 0.2);\n  cursor: default;\n}\n\n.console-input-row button:hover {\n  background: var(--accent-hover);\n  box-shadow: 0 1px 1.5px rgba(0, 0, 0, 0.12), inset 0 0.5px 0 rgba(255, 255, 255, 0.2);\n  transform: none;\n}\n\n.suggestion:active,\n.frag-step:active,\n.console-input-row button:active:not(:disabled),\n.probe-close:active,\n.metric-info-trigger:active {\n  transform: scale(0.96);\n  transition-duration: var(--dur-fast);\n}\n\n/* ------------------------------------------------------------- popovers */\n\n.metric-info-popover {\n  border: 0;\n  border-radius: var(--radius-lg);\n  background: var(--elevated-bg);\n  box-shadow: var(--shadow-float);\n  padding: 10px 12px;\n  animation: popover-in var(--dur-base) var(--ease-spring);\n}\n\n@keyframes popover-in {\n  from { opacity: 0; transform: translateY(-3px) scale(0.98); }\n  to   { opacity: 1; transform: none; }\n}\n\n/* ---------------------------------------------------------- theme control */\n\n.theme-toggle {\n  position: relative;\n  display: inline-grid;\n  grid-auto-flow: column;\n  grid-auto-columns: 30px;\n  height: 24px;\n  padding: 2px;\n  border-radius: 7px;\n  background: var(--fill-hover);\n  box-shadow: inset 0 0 0 0.5px var(--separator);\n}\n\n.theme-toggle-thumb {\n  position: absolute;\n  top: 2px;\n  bottom: 2px;\n  left: 2px;\n  width: 30px;\n  border-radius: 5px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n  transform: translateX(calc(var(--i, 0) * 30px));\n  transition: transform var(--dur-base) var(--ease-spring);\n  pointer-events: none;\n}\n\n.theme-seg {\n  position: relative;\n  z-index: 1;\n  display: grid;\n  place-items: center;\n  padding: 0;\n  border: 0;\n  border-radius: 5px;\n  background: transparent;\n  color: var(--label-2);\n  cursor: default;\n  transition: color var(--dur-fast) ease, transform var(--dur-base) var(--ease-spring);\n}\n\n.theme-seg:hover {\n  color: var(--label-1);\n}\n\n.theme-seg:active {\n  transform: scale(0.92);\n  transition-duration: var(--dur-fast);\n}\n\n.theme-seg[aria-checked="true"] {\n  color: var(--label-1);\n}\n\n.theme-seg svg {\n  width: 14px;\n  height: 14px;\n}\n\n/* ----------------------------------------------------------------- notices */\n\n.error-banner {\n  flex-shrink: 0;\n  margin: var(--space-3) var(--space-5) 0;\n  padding: 10px 14px;\n  border: 0;\n  border-radius: var(--radius-lg);\n  background: var(--status-red-soft);\n  color: var(--status-red);\n  font-size: var(--font-size-sm);\n}\n\n/* -------------------------------------------- materials without vibrancy */\n\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  .topbar { background: var(--solid-bar); }\n  .finder-sidebar, .finder-details { background: var(--solid-sidebar); }\n}\n\n@media (prefers-reduced-transparency: reduce) {\n  .topbar { background: var(--solid-bar); backdrop-filter: none; -webkit-backdrop-filter: none; }\n  .finder-sidebar, .finder-details {\n    background: var(--solid-sidebar); backdrop-filter: none; -webkit-backdrop-filter: none;\n  }\n  .finder-features .panel > .panel-head, .finder-features .panel > .panel-head::after { transition: none; }\n}\n\n/* ------------------------------------------------------------- narrow widths */\n\n/* Stacked: one scroll container for the whole page, so the columns flow one\n   after another instead of each clipping its own content. */\n@media (max-width: 1100px) {\n  .finder-layout {\n    flex-direction: column;\n    overflow-y: auto;\n  }\n  .finder-content {\n    flex: none;\n    flex-direction: column;\n    overflow: visible;\n  }\n  .finder-sidebar {\n    flex: none;\n    width: 100%;\n    min-width: 0;\n    max-height: 220px;\n    border-right: 0;\n    border-bottom: 1px solid var(--separator);\n  }\n  .finder-features {\n    flex: none;\n    min-height: auto;\n    overflow: visible;\n    padding: 0 var(--space-5) var(--space-6);\n  }\n  .finder-details {\n    flex: none;\n    width: 100%;\n    min-width: 0;\n    min-height: auto;\n    overflow: visible;\n    border-left: 0;\n    border-top: 1px solid var(--separator);\n  }\n  .console-panel { height: 420px; }\n}\n\n@media (max-width: 620px) {\n  .topbar { height: auto; flex-wrap: wrap; padding: 10px 14px; }\n  .topbar-trailing { width: 100%; justify-content: space-between; margin-left: 0; }\n  .wordmark-sub { display: none; }\n}\n\n/* the always-visible tour control, and the case cross-fade */\n.tour-btn {\n  height: 28px; padding: 0 12px; border: 0; border-radius: 7px; cursor: default;\n  background: var(--control-bg); color: var(--label-1); box-shadow: var(--shadow-control);\n  font: inherit; font-size: var(--font-size-sm); font-weight: var(--font-weight-medium);\n}\n.tour-btn:hover { background: var(--control-bg-hover); }\n.tour-btn.is-on { background: var(--accent); color: var(--on-accent); }\n/* Switching case: the old case softens into the background - dimmer, slightly\n   blurred, a hair smaller - while the next loads; the new case then rises into\n   focus. A thin progress sweep appears only if loading takes more than a beat. */\n.finder-content { position: relative; transition: opacity 240ms ease, filter 240ms ease, transform 240ms cubic-bezier(0.22, 1, 0.36, 1); }\n.finder-content.is-leaving { opacity: 0.4; filter: blur(4px) saturate(0.9); transform: scale(0.992); }\n.finder-content.is-leaving::before {\n  content: ""; position: absolute; left: 0; right: 0; top: 0; z-index: 20; height: 2px; pointer-events: none;\n  background: linear-gradient(90deg, transparent, var(--accent), #64d2ff, transparent); background-size: 40% 100%; background-repeat: no-repeat;\n  animation: case-load 1100ms 180ms ease-in-out infinite backwards;\n}\n@keyframes case-load { from { background-position: -40% 0; opacity: 1; } to { background-position: 140% 0; opacity: 1; } }\n.finder-content > .finder-features, .finder-content > .finder-details { animation: st-case-in 380ms cubic-bezier(0.22, 1, 0.36, 1); }\n@keyframes st-case-in { from { opacity: 0; translate: 0 10px; filter: blur(6px); } }\n\n@media (prefers-reduced-motion: reduce) {\n  .finder-content > .finder-features, .finder-content > .finder-details { animation: none; }\n}\n\n/* ================================================================== cards */\n/* Every section is a card on a soft pane: its own surface, a hairline edge and\n   a soft shadow, leaning away from the pointer (tilt.js) with a light that\n   follows it. Sticky headers keep their scroll-edge effect, in the card\'s colour. */\n:root { --pane-bg: #f2f2f5; --card-bg: #ffffff; --sheen-rgb: 10, 132, 255; --sheen-max: 0.06; }\n:root[data-theme="dark"] { --pane-bg: #19191b; --card-bg: #232326; --sheen-rgb: 255, 255, 255; --sheen-max: 0.07; }\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) { --pane-bg: #19191b; --card-bg: #232326; --sheen-rgb: 255, 255, 255; --sheen-max: 0.07; }\n}\n@property --sheen { syntax: "<number>"; inherits: false; initial-value: 0; }\n\n.finder-features {\n  background:\n    radial-gradient(900px 500px at 12% -10%, rgba(10, 132, 255, 0.07), transparent 60%),\n    radial-gradient(800px 600px at 110% 20%, rgba(90, 200, 250, 0.05), transparent 60%),\n    var(--pane-bg);\n}\n.finder-features > .panel,\n.finder-details > .cg,\n.finder-details > .panel {\n  position: relative;\n  margin-top: var(--space-5);\n  padding: var(--space-5) var(--space-6) var(--space-6);\n  border: 0;\n  border-radius: 18px;\n  background:\n    radial-gradient(560px circle at var(--mx, 50%) var(--my, 0%), rgba(var(--sheen-rgb), calc(var(--sheen) * var(--sheen-max))), transparent 45%),\n    var(--card-bg);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 1px 2px rgba(0, 0, 0, 0.05), 0 10px 30px rgba(0, 0, 0, 0.07);\n  transform: perspective(1400px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg));\n  transition: transform 700ms cubic-bezier(0.22, 1.2, 0.36, 1), box-shadow 300ms ease, --sheen 400ms ease;\n  animation: card-in 520ms cubic-bezier(0.22, 1.2, 0.36, 1) backwards;\n}\n.finder-features > .panel:first-child { margin-top: var(--space-6); }\n.finder-features > .panel.is-tilting,\n.finder-details > .cg.is-tilting,\n.finder-details > .panel.is-tilting {\n  --sheen: 1;\n  transition: transform 160ms ease-out, box-shadow 300ms ease, --sheen 300ms ease;\n  box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.45), 0 2px 4px rgba(0, 0, 0, 0.06), 0 18px 44px rgba(0, 0, 0, 0.12);\n}\n/* the entrance: a separate property from the tilt\'s transform, so they never fight */\n@keyframes card-in { from { opacity: 0; translate: 0 12px; } }\n.finder-features > .panel:nth-child(2) { animation-delay: 40ms; }\n.finder-features > .panel:nth-child(3) { animation-delay: 80ms; }\n.finder-features > .panel:nth-child(4) { animation-delay: 120ms; }\n.finder-features > .panel:nth-child(5) { animation-delay: 160ms; }\n.finder-features > .panel:nth-child(n+6) { animation-delay: 200ms; }\n\n/* sticky headers inside a card: fill the card\'s width and top corners when stuck */\n.finder-features > .panel > .panel-head {\n  margin: calc(-1 * var(--space-5)) calc(-1 * var(--space-6)) 14px;\n  padding: var(--space-4) var(--space-6) var(--space-3);\n  border-radius: 18px 18px 0 0;\n}\n.finder-features > .panel > .panel-head.is-stuck { background: var(--card-bg); }\n.finder-features > .panel > .panel-head::after { background: linear-gradient(to bottom, var(--card-bg), transparent); }\n.finder-features .panel { padding-top: var(--space-5); }\n\n/* sections that were boxes of their own, or separated by rules, are cards now */\n.finder-features > .panel.finding { margin-top: var(--space-6); }\n.finder-details > .cg { border-bottom: 0; margin-bottom: 0; padding: var(--space-4) var(--space-4) var(--space-4); }\n.finder-details > .panel { padding: var(--space-4); }\n.finder-details > .cg:first-of-type { margin-top: var(--space-4); }\n\n/* the jump-to ring now outlines every card evenly */\n.finder-features > .panel.cg-flash::after,\n.finder-details > .cg.cg-flash::after { inset: -6px; border-radius: 24px; }\n\n@media (prefers-reduced-motion: reduce) {\n  .finder-features > .panel, .finder-details > .cg, .finder-details > .panel { animation: none; transform: none; }\n}\n\n/* a row of two supporting cards: the same card treatment as the rest of the column */\n.finder-features > .card-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-5); align-items: start; margin-top: var(--space-5); }\n.finder-features > .card-row > .panel {\n  position: relative; margin-top: 0; padding: var(--space-5) var(--space-5) var(--space-5); border: 0; border-radius: 18px;\n  background:\n    radial-gradient(560px circle at var(--mx, 50%) var(--my, 0%), rgba(var(--sheen-rgb), calc(var(--sheen) * var(--sheen-max))), transparent 45%),\n    var(--card-bg);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 1px 2px rgba(0, 0, 0, 0.05), 0 10px 30px rgba(0, 0, 0, 0.07);\n  transform: perspective(1400px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg));\n  transition: transform 700ms cubic-bezier(0.22, 1.2, 0.36, 1), box-shadow 300ms ease, --sheen 400ms ease;\n  animation: card-in 520ms cubic-bezier(0.22, 1.2, 0.36, 1) backwards 200ms;\n}\n.finder-features > .card-row > .panel.is-tilting {\n  --sheen: 1; transition: transform 160ms ease-out, box-shadow 300ms ease, --sheen 300ms ease;\n  box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.45), 0 2px 4px rgba(0, 0, 0, 0.06), 0 18px 44px rgba(0, 0, 0, 0.12);\n}\n.finder-features > .card-row > .panel > .panel-head {\n  margin: calc(-1 * var(--space-5)) calc(-1 * var(--space-5)) 14px; padding: var(--space-4) var(--space-5) var(--space-3); border-radius: 18px 18px 0 0;\n}\n.finder-features > .card-row > .panel > .panel-head.is-stuck { background: var(--card-bg); }\n.finder-features > .card-row > .panel > .panel-head::after { background: linear-gradient(to bottom, var(--card-bg), transparent); }\n.finder-features > .card-row > .panel.cg-flash::after { inset: -6px; border-radius: 24px; }\n@media (max-width: 1100px) { .finder-features > .card-row { grid-template-columns: 1fr; } }\n@media (prefers-reduced-motion: reduce) { .finder-features > .card-row > .panel { animation: none; transform: none; } }\n\n/* ======================================================= scroll-triggered motion */\n/* A card\'s animations wait, in their start state, until it scrolls into view\n   (inView.js adds is-inview): the card fades up, then its charts draw. */\n:is(.finder-features > .panel, .finder-features > .card-row > .panel, .finder-details > .cg, .finder-details > .panel):not(.is-inview),\n:is(.finder-features > .panel, .finder-features > .card-row > .panel, .finder-details > .cg, .finder-details > .panel):not(.is-inview)\n  :is(.lc-line, .lc-area, .lc-dot, .bt-bar, .bt-val, .fr-dot, .os-glyph-shape, .os-glyph-axis, .cf-pips i, .cv-fill, .pv-bar,\n      .gate-dot, .rv-row, .whatif-row) {\n  animation-play-state: paused;\n}\n:is(.finder-features > .panel, .finder-features > .card-row > .panel):not(.is-inview) .cf-naive.is-struck .cf-key > span::after {\n  animation-play-state: paused;\n}\n/* the card itself arrives from a little lower, once, when first seen */\n.finder-features > .panel, .finder-features > .card-row > .panel, .finder-details > .cg, .finder-details > .panel {\n  animation-delay: 0ms;\n}\n'}}
CL_OLD = 'groups and hides when its group is closed; a small legend explains the symbols.\n'
CL_NEW = 'groups and hides when its group is closed; a small legend explains the symbols.\n\n**Smoother case switching.** The leaving case softens into the background - dimmer, lightly\nblurred, a hair smaller - and a thin progress sweep appears only if the next takes more than a\nbeat to load; the new case then rises into focus. The sidebar selection glides between rows on a\ngentle spring with a soft glow. Reduced motion turns all of it off.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing - apply patch 43 first")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for (is patch 43 applied?); send its sha256")
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 43 entry this appends after was not found - apply patch 43 first")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 44: {len(writes)} files written, {skipped} already in place.")
